def minNewCables(n, edges):
    m = len(edges)
    adj = [[] for _ in range(n)]
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))
    disc = [-1] * n
    low = [0] * n
    is_bridge = [False] * m
    disc[0] = low[0] = 0
    timer = 1
    work = [(0, -1, 0)]
    while work:
        u, pe, i = work.pop()
        if i < len(adj[u]):
            work.append((u, pe, i + 1))
            v, e = adj[u][i]
            if e == pe:
                continue
            if disc[v] == -1:
                disc[v] = low[v] = timer
                timer += 1
                work.append((v, e, 0))
            elif disc[v] < low[u]:
                low[u] = disc[v]
        elif work:
            parent = work[-1][0]
            if low[u] < low[parent]:
                low[parent] = low[u]
            if low[u] > disc[parent]:
                is_bridge[pe] = True
    root = list(range(n))

    def find(x):
        while root[x] != x:
            root[x] = root[root[x]]
            x = root[x]
        return x

    for i, (u, v) in enumerate(edges):
        if not is_bridge[i]:
            root[find(u)] = find(v)
    deg = {}
    for i, (u, v) in enumerate(edges):
        if is_bridge[i]:
            a, b = find(u), find(v)
            deg[a] = deg.get(a, 0) + 1
            deg[b] = deg.get(b, 0) + 1
    leaves = sum(1 for d in deg.values() if d == 1)
    return (leaves + 1) // 2
